import re
def rle_encode(s: str) -> str:
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(str(j - i) + s[i])
        i = j
    return "".join(out)

def rle_decode(s: str) -> str:
    return "".join(ch * int(n) for n, ch in re.findall(r"([0-9]+)([^0-9])", s))

