import re
def parse_duration(s: str) -> int:
    if not re.fullmatch(r"([0-9]+[dhms])+", s):
        raise ValueError("bad duration")
    mult = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen = set()
    total = 0
    for n, u in re.findall(r"([0-9]+)([dhms])", s):
        if u in seen:
            raise ValueError("repeated unit")
        seen.add(u)
        total += int(n) * mult[u]
    return total

