def fizzbuzz_rules(n: int, rules: list[tuple[int, str]]) -> list[str]:
    for d, _ in rules:
        if d < 1:
            raise ValueError("divisor must be >= 1")
    out = []
    for i in range(1, n + 1):
        s = "".join(w for d, w in rules if i % d == 0)
        out.append(s or str(i))
    return out

