import re
_PAIRS = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
          (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]

def to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError("out of range")
    out = []
    for v, r in _PAIRS:
        while n >= v:
            out.append(r)
            n -= v
    return "".join(out)

def from_roman(s: str) -> int:
    if not re.fullmatch(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})", s) or s == "":
        raise ValueError("invalid roman numeral")
    total = 0
    for v, r in _PAIRS:
        while s.startswith(r):
            total += v
            s = s[len(r):]
    return total

