import re
_NUM = r"(?:0|[1-9][0-9]*)"
_PRE = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_BLD = r"[0-9A-Za-z-]+"
_RE = re.compile(rf"({_NUM})\.({_NUM})\.({_NUM})(?:-({_PRE}(?:\.{_PRE})*))?(?:\+{_BLD}(?:\.{_BLD})*)?")

def _parse(v):
    m = _RE.fullmatch(v)
    if not m:
        raise ValueError("invalid version")
    core = tuple(int(m.group(i)) for i in (1, 2, 3))
    pre = m.group(4).split(".") if m.group(4) is not None else None
    return core, pre

def _cmp(x, y):
    return (x > y) - (x < y)

def compare_semver(a: str, b: str) -> int:
    ca, pa = _parse(a)
    cb, pb = _parse(b)
    if ca != cb:
        return _cmp(ca, cb)
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1
    for x, y in zip(pa, pb):
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            if int(x) != int(y):
                return _cmp(int(x), int(y))
        elif xn:
            return -1
        elif yn:
            return 1
        elif x != y:
            return _cmp(x, y)
    return _cmp(len(pa), len(pb))

