def parse_ini(text: str) -> dict[str, dict[str, str]]:
    result = {}
    current = ""
    glob = {}
    sec = glob
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in ";#":
            continue
        if line[0] == "[":
            if not line.endswith("]"):
                raise ValueError("bad section")
            name = line[1:-1].strip()
            if not name:
                raise ValueError("empty section")
            sec = result.setdefault(name, {})
            continue
        if "=" not in line:
            raise ValueError("no =")
        k, v = line.split("=", 1)
        k = k.strip()
        if not k:
            raise ValueError("empty key")
        sec[k] = v.strip()
    if glob:
        result = {"": glob, **result}
    return result

