_DIG = "0123456789abcdefghijklmnopqrstuvwxyz"

def _check(base):
    if not isinstance(base, int) or not 2 <= base <= 36:
        raise ValueError("bad base")

def to_base(n: int, base: int) -> str:
    _check(base)
    if n == 0:
        return "0"
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, base)
        out.append(_DIG[r])
    return ("-" if neg else "") + "".join(reversed(out))

def from_base(s: str, base: int) -> int:
    _check(base)
    neg = s.startswith("-")
    body = s[1:] if neg else s
    if not body:
        raise ValueError("no digits")
    val = 0
    for ch in body:
        d = _DIG.find(ch.lower()) if ch.isascii() else -1
        if d < 0 or d >= base:
            raise ValueError("bad digit")
        val = val * base + d
    return -val if neg else val

