def eval_expr(s: str) -> int:
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c in " \t":
            i += 1
        elif c in "0123456789":
            j = i
            while j < len(s) and s[j] in "0123456789":
                j += 1
            toks.append(("n", int(s[i:j])))
            i = j
        elif c in "+-*/%()":
            toks.append((c, None))
            i += 1
        else:
            raise ValueError("bad char")
    pos = 0

    def peek():
        return toks[pos][0] if pos < len(toks) else None

    def expr():
        nonlocal pos
        node = term()
        while peek() in ("+", "-"):
            op = toks[pos][0]
            pos += 1
            node = (op, node, term())
        return node

    def term():
        nonlocal pos
        node = unary()
        while peek() in ("*", "/", "%"):
            op = toks[pos][0]
            pos += 1
            node = (op, node, unary())
        return node

    def unary():
        nonlocal pos
        if peek() == "-":
            pos += 1
            return ("neg", unary())
        return atom()

    def atom():
        nonlocal pos
        p = peek()
        if p == "n":
            v = toks[pos][1]
            pos += 1
            return ("n", v)
        if p == "(":
            pos += 1
            node = expr()
            if peek() != ")":
                raise ValueError("expected )")
            pos += 1
            return node
        raise ValueError("unexpected token")

    tree = expr()
    if pos != len(toks):
        raise ValueError("trailing tokens")

    def ev(t):
        k = t[0]
        if k == "n":
            return t[1]
        if k == "neg":
            return -ev(t[1])
        a, b = ev(t[1]), ev(t[2])
        if k == "+":
            return a + b
        if k == "-":
            return a - b
        if k == "*":
            return a * b
        if k == "/":
            return a // b
        return a % b

    return ev(tree)

