import re

def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("must start with /")
    raw = pointer[1:].split("/")
    tokens = []
    for t in raw:
        if re.search(r"~(?![01])", t):
            raise ValueError("bad escape")
        tokens.append(re.sub(r"~([01])", lambda m: "~" if m.group(1) == "0" else "/", t))
    cur = doc
    for t in tokens:
        if isinstance(cur, dict):
            if t not in cur:
                raise KeyError(t)
            cur = cur[t]
        elif isinstance(cur, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", t):
                raise ValueError("bad index")
            i = int(t)
            if i >= len(cur):
                raise IndexError(i)
            cur = cur[i]
        else:
            raise KeyError(t)
    return cur

