import heapq

def shortest_path(graph: dict, start: str, goal: str):
    for u, nbrs in graph.items():
        for v, w in nbrs.items():
            if w < 1:
                raise ValueError("weight must be >= 1")
    if start == goal:
        return (0, [start])
    rev = {}
    for u, nbrs in graph.items():
        for v, w in nbrs.items():
            rev.setdefault(v, []).append((u, w))
    dist = {goal: 0}
    heap = [(0, goal)]
    while heap:
        d, v = heapq.heappop(heap)
        if d > dist.get(v, float("inf")):
            continue
        for u, w in rev.get(v, []):
            nd = d + w
            if nd < dist.get(u, float("inf")):
                dist[u] = nd
                heapq.heappush(heap, (nd, u))
    if start not in dist:
        return None
    path = [start]
    cur = start
    while cur != goal:
        best = None
        for v, w in graph.get(cur, {}).items():
            if v in dist and w + dist[v] == dist[cur]:
                if best is None or v < best:
                    best = v
        path.append(best)
        cur = best
    return (dist[start], path)

