import re
from datetime import datetime, timedelta, time

_ITEM = re.compile(r"(\*|([0-9]+)(?:-([0-9]+))?)(?:/([0-9]+))?")

def _field(text, lo, hi):
    vals = set()
    for item in text.split(","):
        m = _ITEM.fullmatch(item)
        if not m:
            raise ValueError("bad item")
        base, a, b, step = m.group(1), m.group(2), m.group(3), m.group(4)
        if base == "*":
            x, y = lo, hi
        elif b is not None:
            x, y = int(a), int(b)
        else:
            if step is not None:
                raise ValueError("step on single value")
            x = y = int(a)
        if step is not None and int(step) == 0:
            raise ValueError("step 0")
        if not (lo <= x <= y <= hi):
            raise ValueError("range")
        vals.update(range(x, y + 1, int(step) if step is not None else 1))
    return vals

def cron_next(expr: str, after: datetime) -> datetime:
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("need 5 fields")
    mins = sorted(_field(parts[0], 0, 59))
    hours = sorted(_field(parts[1], 0, 23))
    doms = _field(parts[2], 1, 31)
    months = _field(parts[3], 1, 12)
    dows = _field(parts[4], 0, 6)
    both = parts[2] != "*" and parts[4] != "*"
    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    day = start.date()
    for _ in range(3660):
        if day.month in months:
            dm = day.day in doms
            dw = (day.weekday() + 1) % 7 in dows
            if (dm or dw) if both else (dm and dw):
                for h in hours:
                    for m in mins:
                        cand = datetime.combine(day, time(h, m))
                        if cand >= start:
                            return cand
        day += timedelta(days=1)
    raise ValueError("no matching time")

def edit_ops(a: str, b: str) -> list[tuple]:
    n, m = len(a), len(b)
    d = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n, -1, -1):
        for j in range(m, -1, -1):
            if i == n:
                d[i][j] = m - j
            elif j == m:
                d[i][j] = n - i
            elif a[i] == b[j]:
                d[i][j] = d[i + 1][j + 1]
            else:
                d[i][j] = 1 + min(d[i + 1][j + 1], d[i + 1][j], d[i][j + 1])
    ops = []
    i = j = 0
    while i < n or j < m:
        cur = d[i][j]
        if i < n and j < m and a[i] == b[j] and d[i + 1][j + 1] == cur:
            ops.append(("keep", a[i])); i += 1; j += 1
        elif i < n and j < m and d[i + 1][j + 1] + 1 == cur:
            ops.append(("sub", a[i], b[j])); i += 1; j += 1
        elif i < n and d[i + 1][j] + 1 == cur:
            ops.append(("del", a[i])); i += 1
        else:
            ops.append(("ins", b[j])); j += 1
    return ops

