def _apply(ops):
    ra, rb = [], []
    for o in ops:
        if o[0] == "keep":
            ra.append(o[1]); rb.append(o[1])
        elif o[0] == "sub":
            ra.append(o[1]); rb.append(o[2])
        elif o[0] == "del":
            ra.append(o[1])
        else:
            rb.append(o[1])
    return "".join(ra), "".join(rb)

def _dist(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

