from functools import lru_cache

def regex_search(pattern: str, text: str) -> bool:
    start = pattern.startswith("^")
    body = pattern[1:] if start else pattern
    end = body.endswith("$") and (len(pattern) > 1 or not start) and len(body) >= 1
    if pattern == "^":
        end = False
    if end:
        body = body[:-1]
    tokens = []
    for ch in body:
        if ch in "*+?":
            if not tokens or tokens[-1][1] is not None:
                raise ValueError("nothing to repeat")
            tokens[-1] = (tokens[-1][0], ch)
        else:
            tokens.append((ch, None))
    n = len(text)

    @lru_cache(maxsize=None)
    def f(ai, ti):
        if ai == len(tokens):
            return (not end) or ti == n
        atom, q = tokens[ai]
        ok = ti < n and (atom == "." or text[ti] == atom)
        if q is None:
            return ok and f(ai + 1, ti + 1)
        if q == "?":
            return (ok and f(ai + 1, ti + 1)) or f(ai + 1, ti)
        if q == "*":
            return f(ai + 1, ti) or (ok and f(ai, ti + 1))
        return ok and (f(ai + 1, ti + 1) or f(ai, ti + 1))

    starts = [0] if start else range(n + 1)
    return any(f(0, s) for s in starts)

def find_free_slots(busy, windows, min_duration, buffer=0):
    if min_duration < 1:
        raise ValueError("min_duration")
    if buffer < 0:
        raise ValueError("buffer")
    blocked = []
    for s, e in busy:
        if s > e:
            raise ValueError("bad busy interval")
        if s < e:
            blocked.append((s - buffer, e + buffer))
    for ws, we in windows:
        if ws >= we:
            raise ValueError("bad window")
    blocked.sort()
    out = []
    for ws, we in windows:
        cur = ws
        for s, e in blocked:
            if e <= cur:
                continue
            if s >= we:
                break
            if s > cur and s - cur >= min_duration:
                out.append((cur, s))
            cur = max(cur, e)
            if cur >= we:
                break
        if cur < we and we - cur >= min_duration:
            out.append((cur, we))
    return out

